/// <summary>
/// Extension of the SalesParmLine table to support custom logic during sales order posting.
/// </summary>
/// <remarks>
/// This class is used to enhance or override standard behavior related to sales order invoice processing,
/// particularly for scenarios involving catch weight items, return orders, or custom pricing logic.
/// Additional methods or overrides in this extension may manipulate line-level invoice data such as
/// LineAmount, SalesPrice, or discount handling based on business-specific rules.
/// </remarks>
[ExtensionOf(tableStr(SalesParmLine))]
final class METSalesParmLine_Extension
{
}

Method.Source:
/// <summary>
/// Overrides the setLineAmount method to apply custom CW (Catch Weight) credit logic for return orders.
/// </summary>
/// <param name="_salesLine">The SalesLine record being processed for invoicing.</param>
/// <remarks>
/// This method checks if the item is catch weight enabled and part of a return order.
/// If CW credit is applicable, it calculates the adjusted line amount using CW logic,
/// sets the SalesPrice to zero, and updates the SalesLine with the new LineAmount.
/// The SkipPriceDiscCalc flag is set to prevent system recalculation during posting.
/// </remarks>
void setLineAmount(SalesLine _salesLine)
{
    next setLineAmount(_salesLine);

    if (_salesLine.inventTable().pdsCWItem() &&
        _salesLine.salesTable().ReturnItemNum && 
        SalesParmLine::isCWClaimCreditApplicable(_salesLine))
    {
        ttsbegin;
        _salesLine.selectForUpdate(true);
        LineAmount lineAmount =  SalesParmLine::processCWClaimCreditAmount(_salesLine);
        _salesLine.LineAmount = lineAmount;
        _salesLine.SalesPrice = 0;
        _salesLine.update();
        ttscommit;

        this.LineAmount = lineAmount;
    }
}

/// <summary>
/// Validates whether CW credit logic should be applied to the given return sales line.
/// </summary>
/// <param name="_salesLine">The return order sales line</param>
/// <returns>True if CW credit logic is applicable; otherwise, false</returns>
public static boolean isCWClaimCreditApplicable(SalesLine _salesLine)
{
    METCustParameters arParams = METCustParameters::find();
    METCWReturnWeight cwReturnWeight = _salesLine.metSalesLine().CWReturnWeight;

    // Validate disposition code and CW return weight
    if (_salesLine.ReturnDispositionCodeId && 
        arParams.CWClaimDispositionCodeId && 
        (_salesLine.ReturnDispositionCodeId != arParams.CWClaimDispositionCodeId) || 
        !cwReturnWeight)
    {
        return false;
    }

    // Validate catch weight item setup
    InventTable inventTable = InventTable::find(_salesLine.ItemId);

    if (!inventTable || !inventTable.pdsCWItem())
    {
        return false;
    }

    return true;
}

/// <summary>
/// Applies CW credit logic to a return sales line by updating price components and line amount.
/// </summary>
/// <param name="_salesLine">The return order sales line</param>
public static METCWReturnWeight processCWClaimCreditAmount(SalesLine _salesLine)
{
    METCWReturnWeight cwReturnWeight = _salesLine.metSalesLine().CWReturnWeight;

    // Join METSalesLinePriceComponent with METComponentCode in a single query
    METSalesLinePriceComponent priceComponent;
    METComponentCode componentCode;

    SalesId originalSalesId = _salesLine.salesTable().metSalesTable().OriginalInvoice;
    SalesLine originalSalesLine;
    InventTransId originalInventTransId;

    select firstonly InventTransId from originalSalesLine
        where originalSalesLine.SalesId == originalSalesId
        && originalSalesLine.ItemId == _salesLine.ItemId;

    originalInventTransId = originalSalesLine.InventTransId;

    select firstonly Value from priceComponent
        exists join componentCode
            where componentCode.Component == priceComponent.Component
            && priceComponent.InventTransId == originalInventTransId
               && componentCode.PriceComponent == METPriceComponent::BasePrice;

    return priceComponent.Value * cwReturnWeight;
}
